import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u13")

L(1, "Perguntas de sim ou não", "Verbo primeiro: Werk je hier? Heb je tijd?",
  ["Fazer perguntas de sim/não", "Responder com ja/nee e frases curtas"],
  vocab=[V("v-tijd","tijd","tempo","noun","de",note="Heb je tijd? = Tens tempo?"), V("v-zin","zin","vontade","noun","de",note="Heb je zin in koffie? = Apetece-te um café?"),
         V("v-natuurlijk","natuurlijk","claro|naturalmente","adverb"), V("v-misschien","misschien","talvez","adverb")],
  ex=[("Heb je tijd?","Tens tempo?"),("Werk je morgen?","Trabalhas amanhã?"),("Ja, natuurlijk!","Sim, claro!"),("Misschien.","Talvez.")],
  gram=[G("g-perguntas-sim-nao","Perguntas de sim/não","O **verbo vai para o início** e o sujeito vem a seguir: *Jij werkt hier* → ***Werk jij** hier?* (o -t cai com jij/je). A entoação sobe no fim, como em português.",
    [("Is hij thuis?","Ele está em casa?"),("Spreekt u Engels?","Fala inglês?")],
    "Em português basta mudar a entoação («Trabalhas aqui?»); em neerlandês também se muda a ordem.")],
  review=["v-hebben","v-werken","v-ja","v-nee","v-morgen"],
  exs=[
    WO("Tens tempo?", ["Heb","je","tijd?"], "Verbo primeiro.", ["v-tijd","v-hebben"]),
    WO("Trabalhas amanhã?", ["Werk","je","morgen?"], "Werk (sem -t) + je.", ["v-werken","v-morgen"]),
    MA([("tijd","tempo"),("zin","vontade"),("natuurlijk","claro"),("misschien","talvez")], "Palavras desta lição.", ["v-tijd","v-zin","v-natuurlijk","v-misschien"]),
    FE(["Werkt","je","hier?"], 0, "Werk", "Com je depois do verbo, o -t cai: werk je?", ["v-werken"]),
    TR("pt-nl","Ela está em casa?", ["Is [zij|ze] thuis"], "Is + sujeito + resto.", ["v-thuis"], bank=["Is","ze","thuis?","Zij","is","ben"]),
    TR("nl-pt","Heb je zin in koffie?", ["Apetece-te (um )café","Queres (um )café","Tens vontade de (tomar )(um )café"], "zin hebben in = apetecer.", ["v-zin"]),
    DL([("Tom","Heb je zin in een biertje?","Apetece-te uma cerveja?"),("Eva","")], ["*Ja, natuurlijk!","Ja, ik heb tijd zin.|Mistura duas expressões.","Nee, ik ben bier.|Não faz sentido."], "Resposta curta e natural.", ["v-natuurlijk","v-zin"]),
    LI("Spreek je Engels?", ["Spreek je Engels"], "Falas inglês?", "Verbo primeiro, -t cai.", ["v-spreken"]),
    CJ("komen","jij","___ jij morgen?", ["Kom"], "Pergunta com jij: kom.", ["v-komen"]),
    TR("nl-pt","Misschien morgen.", ["Talvez amanhã"], "misschien = talvez.", ["v-misschien","v-morgen"]),
  ], diff=2, mins=5)

L(2, "Quem, o quê, onde, quando", "As palavras interrogativas mais frequentes.",
  ["Usar wie, wat, waar e wanneer"],
  vocab=[V("v-wie","wie","quem","pronoun"), V("v-wanneer","wanneer","quando","adverb"),
         V("v-waarom","waarom","porquê|porque","adverb"), V("v-welk","welk","qual|que","determiner",note="welk com palavras het; welke com de e plural.")],
  ex=[("Wie is dat?","Quem é aquele?"),("Wanneer kom je?","Quando vens?"),("Waarom leer je Nederlands?","Porque aprendes neerlandês?"),("Welke trein?","Que comboio?")],
  gram=[G("g-interrogativas","Palavras interrogativas","Com palavra interrogativa, ela ocupa a 1.ª posição e o **verbo vem logo a seguir**: *Waar **woon** je?*, *Wanneer **kom** je?*. **welk** + palavra het (*welk huis*), **welke** + palavra de ou plural (*welke trein*, *welke boeken*).",
    [("Wat drink je?","O que bebes?"),("Wie heeft mijn pen?","Quem tem a minha caneta?")])],
  review=["v-wat","v-waar","v-hoe","v-komen"],
  exs=[
    MA([("wie","quem"),("wat","o quê"),("waar","onde"),("wanneer","quando"),("waarom","porquê")], "Interrogativas.", ["v-wie","v-wat","v-waar","v-wanneer","v-waarom"]),
    MC("Quer saber a hora de chegada de alguém. Que palavra usa?", ["*wanneer","waar|«waar» = onde.","wie|«wie» = quem."], "wanneer = quando.", ["v-wanneer"]),
    MC("___ trein gaat naar Utrecht? (que)", ["*Welke","Welk|«trein» é de: welke."], "de trein → welke.", ["v-welk"]),
    WO("Quando vens?", ["Wanneer","kom","je?"], "Interrogativa + verbo + sujeito.", ["v-wanneer","v-komen"]),
    TR("pt-nl","Quem é aquela mulher?", ["Wie is die vrouw"], "die vrouw = aquela mulher.", ["v-wie","v-die"]),
    TR("nl-pt","Waarom leer je Nederlands?", ["Porque (é que )aprendes neerlandês","Porque estás a aprender neerlandês"], "waarom = porquê.", ["v-waarom","v-leren"]),
    FE(["Waar","je","woont?"], 1, "woon je", "Depois da interrogativa vem o verbo: waar woon je?", ["v-waar"]),
    FB("___ is je verjaardag? — In mei.", ["Wanneer"], "Quando?", ["v-wanneer"], choices=["Wanneer","Wie","Waar"], tr="Quando é o teu aniversário? — Em maio."),
    LI("Wie heeft mijn sleutel?", ["Wie heeft mijn sleutel"], "Quem tem a minha chave?", "wie + verbo.", ["v-wie","v-sleutel"]),
    DL([("Ana","Waarom ben je moe?","Porque estás cansado?"),("Tom","")], ["*Ik werk veel.","In Utrecht.|Responde a «waar?».","Morgen.|Responde a «wanneer?»."], "A resposta explica o motivo.", ["v-waarom"]),
  ], diff=2, mins=5)

L(3, "Quanto, como e qual", "hoeveel, hoe, hoe laat, welk(e).",
  ["Perguntar quantidades, modo e horas"],
  vocab=[V("v-hoe-laat","hoe laat","a que horas|que horas","expression",note="Hoe laat is het? = Que horas são?"), V("v-veel","veel","muito|muitos","adverb"),
         V("v-weinig","weinig","pouco|poucos","adverb"), V("v-laat","laat","tarde|atrasado","adjective")],
  ex=[("Hoe laat is het?","Que horas são?"),("Hoeveel kost dat?","Quanto custa isso?"),("Hoe ga je naar je werk?","Como vais para o trabalho?")],
  gram=[G("g-hoe-combinacoes","Combinações com hoe","**hoe** junta-se a outras palavras: **hoe laat** (a que horas), **hoe oud** (que idade), **hoeveel** (quanto/quantos — numa só palavra), **hoe lang** (quanto tempo).",
    [("Hoe lang woon je hier?","Há quanto tempo vives aqui?"),("Hoeveel kinderen heb je?","Quantos filhos tens?")])],
  review=["v-hoe","v-hoeveel","v-hoe-oud","v-kosten"],
  exs=[
    MA([("hoe laat","a que horas"),("hoeveel","quanto"),("veel","muito"),("weinig","pouco")], "Quantidades e horas.", ["v-hoe-laat","v-hoeveel","v-veel","v-weinig"]),
    TR("pt-nl","Que horas são?", ["Hoe laat is het"], "Literalmente «quão tarde é?».", ["v-hoe-laat"]),
    TR("pt-nl","Quantos filhos tens?", ["Hoeveel kinderen heb [je|jij]"], "hoeveel + plural.", ["v-hoeveel","v-kind"]),
    MC("Como pergunta «A que horas começa?»", ["*Hoe laat begint het?","Hoeveel begint het?|«hoeveel» = quanto.","Wanneer laat begint het?|Mistura duas formas."], "hoe laat = a que horas.", ["v-hoe-laat"]),
    FB("___ kost een kop koffie?", ["Hoeveel","Wat"], "Hoeveel/Wat kost…?", ["v-hoeveel"], choices=["Hoeveel","Hoe laat","Wie"], tr="Quanto custa uma chávena de café?"),
    TR("nl-pt","Hoe ga je naar je werk?", ["Como vais para o trabalho"], "hoe = como.", ["v-hoe"]),
    FE(["Hoe","veel","kost","dat?"], 0, "Hoeveel", "Escreve-se numa só palavra: hoeveel.", ["v-hoeveel"]),
    LI("Hoe laat is het?", ["Hoe laat is het"], "Que horas são?", "Pergunta essencial.", ["v-hoe-laat"]),
    TR("nl-pt","Ik heb weinig tijd.", ["Tenho pouco tempo"], "weinig = pouco.", ["v-weinig","v-tijd"]),
    WO("Há quanto tempo vives aqui?", ["Hoe","lang","woon","je","hier?"], "hoe lang = quanto tempo.", ["v-wonen","v-hier"]),
  ], diff=2, mins=5)

L(4, "Confirmar: toch? e hè?", "Pequenas perguntas no fim da frase.",
  ["Pedir confirmação com «toch?» e «hè?»", "Reagir com surpresa"],
  vocab=[V("v-toch","toch","não é?|pois não?","particle",note="No fim da frase pede confirmação: Je komt toch?"),
         V("v-he","hè","não é?|né","particle",note="Informal: Mooi weer, hè?"),
         V("v-weer","weer","tempo (meteorológico)","noun","het"), V("v-lekker","lekker","bom|saboroso|agradável","adjective",note="Para comida e para sensações: lekker weer.")],
  ex=[("Je komt morgen, toch?","Vens amanhã, não vens?"),("Lekker weer, hè?","Está um tempo bom, não está?"),("Echt waar?","A sério?")],
  gram=[G("g-toch-he","toch? e hè?","Para pedir confirmação, junta-se **toch?** ou **hè?** ao fim de uma frase normal: *Je bent Portugees, **toch**?* — sem mudar a ordem. São muito frequentes na conversa; **hè** é mais informal.",
    [("Het is koud, hè?","Está frio, não está?")],
    "Equivale ao nosso «não é?», «pois não?» no fim da frase.")],
  review=["v-echt","v-komen","v-portugees","v-koud"],
  exs=[
    MC("Como pede confirmação de que alguém vem amanhã?", ["*Je komt morgen, toch?","Toch je komt morgen?|«toch?» vai no fim.","Komt je morgen toch?|A ordem fica normal e «toch» vai no fim."], "Frase normal + toch?", ["v-toch"]),
    TR("nl-pt","Lekker weer, hè?", ["Está um tempo bom, não está","Que tempo bom, não é","Bom tempo, não é"], "lekker weer = tempo agradável.", ["v-he","v-weer","v-lekker"]),
    TR("pt-nl","És português, não és?", ["Je bent Portugees(,) toch","Jij bent Portugees(,) toch","Je bent Portugees(,) hè"], "toch? / hè? no fim.", ["v-toch","v-portugees"]),
    MA([("toch?","não é?"),("weer","tempo (meteo)"),("lekker","saboroso"),("echt?","a sério?")], "Conversa informal.", ["v-toch","v-weer","v-lekker","v-echt"]),
    AR("weer","o tempo (meteorológico)","het", "«Het weer».", ["v-weer"]),
    EX("Lekker!", "Saboroso!", "O que quer dizer «Lekker!» depois de provar comida?", ["*Que bom! / Está delicioso!","Está frio!|Isso seria «koud».","Que horas são?|Não tem relação."], "lekker = saboroso, agradável.", ["v-lekker"]),
    DL([("Sanne","Je bent toch Portugees?","És português, não és?"),("Pedro","")], ["*Ja, uit Lissabon.","Nee, ik ben Portugees.|«Nee» contradiz o resto.","Toch!|Não responde à pergunta."], "Confirma-se com ja + informação.", ["v-toch"]),
    LI("Het is koud, hè?", ["Het is koud(,) hè"], "Está frio, não está?", "hè com entoação a subir.", ["v-he","v-koud"]),
    FB("Het eten is ___!", ["lekker"], "lekker = saboroso.", ["v-lekker","v-eten"], choices=["lekker","laat","weinig"], tr="A comida está deliciosa!"),
    WO("Vens amanhã, não vens?", ["Je","komt","morgen,","toch?"], "Ordem normal + toch.", ["v-toch"]),
  ], diff=2, mins=5)

L(5, "Entrevista rápida", "Revisão: fazer e responder a várias perguntas.",
  ["Fazer uma pequena entrevista a alguém"],
  ex=[("Hoe heet je? Waar kom je vandaan? Wat doe je?","Como te chamas? De onde és? O que fazes?")],
  review=["v-wie","v-wat","v-waar","v-wanneer","v-waarom","v-hoeveel","v-hoe-laat","v-toch","v-hoe-oud"],
  exs=[
    MA([("Hoe heet je?","Como te chamas?"),("Hoe oud ben je?","Que idade tens?"),("Wat doe je?","O que fazes?"),("Waar woon je?","Onde vives?")], "Perguntas básicas.", ["v-heten","v-hoe-oud","v-doen","v-wonen"]),
    MC("Resposta: «In Leiden.» Qual foi a pergunta?", ["*Waar woon je?","Wanneer kom je?|A resposta seria uma data/hora.","Wie ben je?|A resposta seria um nome."], "Waar? → lugar.", ["v-waar"]),
    MC("Resposta: «Om acht uur.» Qual foi a pergunta?", ["*Hoe laat begint de les?","Hoeveel kost de les?|A resposta seria um preço.","Waar is de les?|A resposta seria um lugar."], "Hoe laat? → hora.", ["v-hoe-laat"]),
    TR("pt-nl","Porque vives nos Países Baixos?", ["Waarom woon [je|jij] in Nederland"], "waarom + verbo + sujeito.", ["v-waarom","v-nederland"]),
    TR("nl-pt","Wanneer begint je werk?", ["Quando começa o teu trabalho","A que horas começas a trabalhar"], "wanneer = quando.", ["v-wanneer"]),
    FE(["Wat","jij","drinkt?"], 1, "drink jij", "Interrogativa + verbo + sujeito: wat drink jij?", ["v-wat"]),
    LI("Hoeveel talen spreek je?", ["Hoeveel talen spreek je"], "Quantas línguas falas?", "hoeveel + plural.", ["v-hoeveel","v-taal"]),
    CO("dialogue","Entrevista na escola de línguas", "Docent: Hoe heet je?\nMarta: Marta.\nDocent: Waar kom je vandaan?\nMarta: Uit Portugal, uit Coimbra.\nDocent: Waarom leer je Nederlands?\nMarta: Ik werk hier, en mijn vriend is Nederlander.",
       [("De onde é a Marta?", ["*De Coimbra","De Lisboa","Do Porto"]),("Porque aprende neerlandês?", ["*Trabalha cá e o namorado é neerlandês","Para viajar","Porque estuda na universidade"])],
       "«mijn vriend» aqui = o meu namorado.", ["v-waarom"]),
    SW("Escreva três perguntas que faria a um novo colega (quem, onde, porquê…).", ["Hoe heet je(?) Waar woon je(?) Waarom leer je Nederlands"],
       ["Três perguntas","Palavra interrogativa + verbo + sujeito","Com je/jij, verbo sem -t"], 6, "Modelo: «Hoe heet je? Waar woon je? Hoe lang werk je hier?»", ["v-wie"]),
    DL([("Colega","Hoe lang woon je al in Nederland?","Há quanto tempo vives nos Países Baixos?"),("Você","")], ["*Twee jaar.","In Amsterdam.|Responde a «waar?».","Om negen uur.|Responde a «hoe laat?»."], "hoe lang? → duração.", ["v-wonen"]),
  ], diff=2, mins=7)

W()
